internal sealed class OutboundWebhookSubscription
{
    private OutboundWebhookSubscription(){}
    internal OutboundWebhookSubscription(string workspaceId,string name,string eventType,string endpoint,string protectedSecret,string actor,DateTimeOffset now){SubscriptionId=$"webhook_{Guid.NewGuid():N}";WorkspaceId=workspaceId;Name=name;EventType=eventType;EndpointUrl=endpoint;Status="DRAFT";Version=0;ProtectedSecret=protectedSecret;CreatedBy=UpdatedBy=actor;CreatedAt=UpdatedAt=now;}
    internal string SubscriptionId{get;private set;}=null!;internal string WorkspaceId{get;private set;}=null!;internal string Name{get;private set;}=null!;internal string EventType{get;private set;}=null!;internal string EndpointUrl{get;private set;}=null!;internal string Status{get;private set;}=null!;internal long Version{get;private set;}internal string ProtectedSecret{get;private set;}=null!;internal string CreatedBy{get;private set;}=null!;internal DateTimeOffset CreatedAt{get;private set;}internal string UpdatedBy{get;private set;}=null!;internal DateTimeOffset UpdatedAt{get;private set;}internal DateTimeOffset? ArchivedAt{get;private set;}
    internal void Update(string name,string eventType,string endpoint,string actor,DateTimeOffset now){RequireEditable();Name=name;EventType=eventType;EndpointUrl=endpoint;Touch(actor,now);}
    internal void Activate(string actor,DateTimeOffset now){if(Status!="DRAFT")throw new InvalidOperationException("Only DRAFT can activate.");Status="ACTIVE";Touch(actor,now);} internal void Pause(string actor,DateTimeOffset now){if(Status!="ACTIVE")throw new InvalidOperationException("Only ACTIVE can pause.");Status="PAUSED";Touch(actor,now);} internal void Resume(string actor,DateTimeOffset now){if(Status!="PAUSED")throw new InvalidOperationException("Only PAUSED can resume.");Status="ACTIVE";Touch(actor,now);} internal void Archive(string actor,DateTimeOffset now){if(Status=="ARCHIVED")throw new InvalidOperationException("Already archived.");Status="ARCHIVED";ArchivedAt=now;Touch(actor,now);}internal void Rotate(string secret,string actor,DateTimeOffset now){if(Status=="ARCHIVED")throw new InvalidOperationException("Archived subscription is immutable.");ProtectedSecret=secret;Touch(actor,now);}
    private void RequireEditable(){if(Status is not("DRAFT" or "PAUSED"))throw new InvalidOperationException("Pause the subscription before editing endpoint or event identity.");}private void Touch(string actor,DateTimeOffset now){Version++;UpdatedBy=actor;UpdatedAt=now;}
}

