internal sealed class OutboundWebhookDelivery{private OutboundWebhookDelivery(){}internal OutboundWebhookDelivery(OutboundWebhookSubscription s,string eventId,long sequence,string eventType,string payload,DateTimeOffset now){DeliveryId=$"delivery_{Guid.NewGuid():N}";SubscriptionId=s.SubscriptionId;WorkspaceId=s.WorkspaceId;EventId=eventId;EventSequence=sequence;EventType=eventType;CanonicalPayloadJson=payload;Status="PENDING";NextAttemptAt=now;CreatedAt=now;}internal string DeliveryId{get;private set;}=null!;internal string SubscriptionId{get;private set;}=null!;internal string WorkspaceId{get;private set;}=null!;internal string EventId{get;private set;}=null!;internal long EventSequence{get;private set;}internal string EventType{get;private set;}=null!;internal string CanonicalPayloadJson{get;private set;}=null!;internal string Status{get;private set;}=null!;internal int AttemptCount{get;private set;}internal DateTimeOffset NextAttemptAt{get;private set;}internal string? ExecutionAttemptId{get;private set;}internal DateTimeOffset? LeaseExpiresAt{get;private set;}internal DateTimeOffset? LastAttemptAt{get;private set;}internal int? LastHttpStatus{get;private set;}internal string? LastErrorCode{get;private set;}internal DateTimeOffset CreatedAt{get;private set;}internal DateTimeOffset? SucceededAt{get;private set;}internal DateTimeOffset? DeadLetteredAt{get;private set;}
 internal void Lease(string id,DateTimeOffset now,DateTimeOffset until){Status="IN_FLIGHT";ExecutionAttemptId=id;LeaseExpiresAt=until;AttemptCount++;LastAttemptAt=now;}internal bool Owns(string id)=>Status=="IN_FLIGHT"&&ExecutionAttemptId==id;internal void Succeed(string id,DateTimeOffset now,int status){Require(id);Status="SUCCEEDED";SucceededAt=now;LastHttpStatus=status;Clear();}internal void Fail(string id,DateTimeOffset now,int? status,string code,bool retryable){Require(id);LastHttpStatus=status;LastErrorCode=code;if(retryable&&AttemptCount<6){Status="RETRY_SCHEDULED";NextAttemptAt=now.Add(RetryDelay(AttemptCount+1));}else{Status="DEAD_LETTER";DeadLetteredAt=now;}Clear();}internal void Replay(DateTimeOffset now){if(Status!="DEAD_LETTER")throw new InvalidOperationException("Only dead-letter deliveries can be replayed.");Status="PENDING";AttemptCount=0;NextAttemptAt=now;DeadLetteredAt=null;LastErrorCode=null;LastHttpStatus=null;}private void Require(string id){if(!Owns(id))throw new InvalidOperationException("Stale delivery execution attempt.");}private void Clear(){ExecutionAttemptId=null;LeaseExpiresAt=null;}private static TimeSpan RetryDelay(int attempt)=>attempt switch{2=>TimeSpan.FromMinutes(1),3=>TimeSpan.FromMinutes(5),4=>TimeSpan.FromMinutes(15),5=>TimeSpan.FromHours(1),6=>TimeSpan.FromHours(6),_=>TimeSpan.Zero};}

